import{_ as d,C as s,o as n,c as a,j as o,a as e,E as l,a2 as i}from"./chunks/framework.B-bxTAy7.js";const C=JSON.parse('{"title":"01 · 嵌入式与 STM32 概览","description":"","frontmatter":{"title":"01 · 嵌入式与 STM32 概览"},"headers":[],"relativePath":"embedded/overview.md","filePath":"embedded/overview.md","lastUpdated":1792416913000}'),g={name:"embedded/overview.md"};function h(p,t,M,c,T,S){const r=s("Meta");return n(),a("div",null,[t[0]||(t[0]=o("h1",{id:"_01-·-嵌入式与-stm32-概览",tabindex:"-1"},[e("01 · 嵌入式与 STM32 概览 "),o("a",{class:"header-anchor",href:"#_01-·-嵌入式与-stm32-概览","aria-label":'Permalink to "01 · 嵌入式与 STM32 概览"'},"​")],-1)),l(r,{time:"25 min",level:"了解",note:"先搞清楚「什么是嵌入式、为什么选 STM32、型号怎么读」，再动手"}),t[1]||(t[1]=i(`<h2 id="结论先行" tabindex="-1">结论先行 <a class="header-anchor" href="#结论先行" aria-label="Permalink to &quot;结论先行&quot;">​</a></h2><ol><li><strong>嵌入式系统 = 藏在设备里、专做一件事的计算机系统</strong>。它和 PC 的根本区别不是「小」，而是<strong>专用 + 资源受限 + 常常要求实时</strong>。</li><li><strong>MCU（单片机）和 MPU（应用处理器）是两条路</strong>：MCU 一片芯片自带 CPU、内存、Flash 和外设，裸机或 RTOS 直接跑；MPU 需要外挂 DDR 和 Flash，跑 Linux。STM32 属于 MCU。</li><li><strong>STM32 = ARM 的 Cortex-M 内核 + 意法半导体（ST）的外设</strong>。内核决定算力和指令集，外设决定能接什么。同一个 HAL 库代码在 F1/F4/H7 之间大部分可移植。</li><li><strong>型号命名是有规律的</strong>：<code>STM32F103C8T6</code> 每一位都有含义，读懂它就读懂了大半选型信息。</li><li><strong>最小系统四要素</strong>：电源、复位、时钟、调试下载口。任何一块能跑的板子都少不了这四样。</li></ol><h2 id="一、什么是嵌入式系统" tabindex="-1">一、什么是嵌入式系统 <a class="header-anchor" href="#一、什么是嵌入式系统" aria-label="Permalink to &quot;一、什么是嵌入式系统&quot;">​</a></h2><p>一个系统只要满足「<strong>以计算机为核心、但用户并不知道里面有个计算机</strong>」，就是嵌入式。洗衣机、电表、遥控器、汽车 ECU 都是；手机、PC 不是——后者的计算机本身就是产品。</p><p>这个定位带来四条硬约束，它们决定了后面所有设计取舍：</p><table tabindex="0"><thead><tr><th>约束</th><th>具体表现</th><th>导致的工程习惯</th></tr></thead><tbody><tr><td><strong>专用</strong></td><td>只做固定的几件事</td><td>不需要通用 OS，裸机或轻量 RTOS 即可</td></tr><tr><td><strong>资源受限</strong></td><td>Flash 几十 KB、RAM 几 KB 到几百 KB</td><td>不能随便 <code>malloc</code>，栈要算着用，避免递归</td></tr><tr><td><strong>实时性</strong></td><td>必须在确定时间内响应</td><td>中断要快进快出，不能随便关中断</td></tr><tr><td><strong>低功耗/成本</strong></td><td>电池供电、百万量产出货</td><td>睡眠模式、关不用的外设时钟、抠每一分钱 BOM</td></tr></tbody></table><blockquote><p>这四条不是「特点」，而是<strong>约束条件</strong>——后面每一章的配置（为什么开时钟、为什么用 DMA、为什么要睡眠）都能追溯到这四条之一。</p></blockquote><h2 id="二、mcu、mpu-与-soc" tabindex="-1">二、MCU、MPU 与 SoC <a class="header-anchor" href="#二、mcu、mpu-与-soc" aria-label="Permalink to &quot;二、MCU、MPU 与 SoC&quot;">​</a></h2><p>这三个词经常被混用，区分标准很实际：<strong>看内存是不是在芯片里面</strong>。</p><table tabindex="0"><thead><tr><th>类型</th><th>内存</th><th>典型主频</th><th>跑什么</th><th>例子</th></tr></thead><tbody><tr><td><strong>MCU</strong> 微控制器</td><td>片内 Flash + SRAM，上电就能跑</td><td>几十 ~ 几百 MHz</td><td>裸机循环 / RTOS（FreeRTOS、RT-Thread）</td><td>STM32F103、GD32、ESP32（MCU 部分）</td></tr><tr><td><strong>MPU</strong> 微处理器</td><td>需外挂 DDR、eMMC，上电要先跑 U-Boot</td><td>几百 MHz ~ 几 GHz</td><td>Linux / Android</td><td>树莓派（博通）、全志、瑞芯微、NXP i.MX</td></tr><tr><td><strong>SoC</strong> 片上系统</td><td>看情况</td><td>—</td><td>强调「把整个系统集成进一颗芯片」</td><td>手机芯片、STM32MP1（Cortex-A + Cortex-M 双核）</td></tr></tbody></table><p>本课程在 MCU 这条线上。判断该用哪条的实用标准：<strong>需要跑 Linux、需要网络协议栈/文件系统/复杂 UI → MPU；只需要定时、采集、控制、简单通信 → MCU</strong>。</p><h2 id="三、arm-cortex-m-内核" tabindex="-1">三、ARM Cortex-M 内核 <a class="header-anchor" href="#三、arm-cortex-m-内核" aria-label="Permalink to &quot;三、ARM Cortex-M 内核&quot;">​</a></h2><p>ARM 自己不造芯片，它卖内核设计（IP），ST、NXP、GD、TI 买过去加上自己的外设做成芯片。所以「STM32」和「Cortex-M」是两个层次的东西：</p><ul><li><strong>Cortex-M 内核</strong>：CPU 本身——寄存器、指令集（Thumb-2）、中断控制器 NVIC、调试接口。</li><li><strong>外设</strong>：GPIO、定时器、ADC、UART、SPI、I²C、DMA……这些是 ST 自己设计的，不同系列差异很大。</li></ul><p>常见 M 系列内核：</p><table tabindex="0"><thead><tr><th>内核</th><th>定位</th><th>关键特性</th><th>代表</th></tr></thead><tbody><tr><td><strong>M0 / M0+</strong></td><td>超低成本、低功耗</td><td>最简单，无除法指令优化</td><td>F0、L0、G0</td></tr><tr><td><strong>M3</strong></td><td>经典主力</td><td>性能与成本平衡，生态最老</td><td><strong>F1（F103）</strong></td></tr><tr><td><strong>M4</strong></td><td>带 DSP 与浮点</td><td><strong>单精度 FPU</strong>，适合电机控制、音频、滤波</td><td><strong>F4（F407）</strong>、F3</td></tr><tr><td><strong>M7</strong></td><td>高性能</td><td>双精度 FPU、Cache、更高主频</td><td>F7、H7</td></tr></tbody></table><p>和经典 8 位单片机（如 8051、AVR）的本质差别是<strong>位宽与地址空间</strong>：32 位数据通路、32 位地址（4 GB 线性地址空间，实际只用了其中一小段放 Flash/SRAM/外设）。这意味着算一个数不用再拆成多次 8 位运算，指针可以直接访问整个空间。</p><h2 id="四、读懂-stm32-的型号" tabindex="-1">四、读懂 STM32 的型号 <a class="header-anchor" href="#四、读懂-stm32-的型号" aria-label="Permalink to &quot;四、读懂 STM32 的型号&quot;">​</a></h2><p>型号不是随机字符串，每一位都有含义。以最经典的 <code>STM32F103C8T6</code> 为例：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>STM32  F   103   C    8    T    6</span></span>
<span class="line"><span> │     │    │    │    │    │    └─ 温度范围：6 = −40~85℃</span></span>
<span class="line"><span> │     │    │    │    │    └────── 封装：T = LQFP，H = BGA，U = VFQFPN</span></span>
<span class="line"><span> │     │    │    │    └─────────── Flash 容量：8 = 64 KB，B = 128 KB，Z = 384 KB…</span></span>
<span class="line"><span> │     │    │    └──────────────── 引脚数：C = 48 脚，R = 64 脚，V = 100 脚，Z = 144 脚</span></span>
<span class="line"><span> │     │    └───────────────────── 子系列：103 = 基础型，407 = 高性能，411…</span></span>
<span class="line"><span> │     └────────────────────────── 产品类别：F = 基础/通用，L = 低功耗，H = 高性能，W = 无线</span></span>
<span class="line"><span> └──────────────────────────────── 家族：STM32</span></span></code></pre></div><p>主流系列怎么选：</p><table tabindex="0"><thead><tr><th>系列</th><th>内核</th><th>主频</th><th>特点</th><th>适合</th></tr></thead><tbody><tr><td><strong>F1</strong>（F103）</td><td>M3</td><td>72 MHz</td><td>最老牌、资料最多、最便宜</td><td>入门学习、成本敏感的量产</td></tr><tr><td><strong>F4</strong>（F407）</td><td>M4</td><td>168 MHz</td><td>带 FPU、外设更全</td><td>需要浮点运算/电机/音频</td></tr><tr><td><strong>L4 / L0</strong></td><td>M4 / M0+</td><td>80 MHz</td><td>低功耗为设计目标</td><td>电池供电</td></tr><tr><td><strong>H7</strong></td><td>M7</td><td>400 MHz+</td><td>高性能、带 Cache</td><td>复杂 UI、高速采集</td></tr><tr><td><strong>G0 / G4</strong></td><td>M0+ / M4</td><td>64 / 170 MHz</td><td>新架构，性价比替代 F1</td><td>新设计选型</td></tr><tr><td><strong>WB / WL</strong></td><td>M4 + 无线</td><td>—</td><td>片内蓝牙 / LoRa</td><td>物联网节点</td></tr></tbody></table><div class="tip custom-block"><p class="custom-block-title">例 1 · 读型号，说出它是什么芯片</p><p><strong>型号 <code>STM32F103C8T6</code></strong>：F = 通用基础型，103 = 基础型子系列（Cortex-M3，最高 72 MHz），C = 48 个引脚，8 = 64 KB Flash，T = LQFP 封装，6 = 工业级温度（−40~85℃）。</p><p>这就是俗称「<strong>蓝色药丸</strong>」的最小系统板上那颗芯片：48 脚、64 KB Flash、20 KB SRAM。它之所以成为入门首选，不是因为性能强，而是因为<strong>资料最多、最便宜、坏了不心疼</strong>。</p><p><strong>再看 <code>STM32F407VET6</code></strong>：F4 = 高性能带 FPU，V = 100 脚，E = 512 KB Flash，T = LQFP。 cortex-M4 内核、168 MHz，是本课程讲时钟树和 DMA 时的另一个参照。</p></div><h2 id="五、选型时到底看什么" tabindex="-1">五、选型时到底看什么 <a class="header-anchor" href="#五、选型时到底看什么" aria-label="Permalink to &quot;五、选型时到底看什么&quot;">​</a></h2><p>选型不是比参数表，而是回答四个问题：</p><ol><li><strong>算力够不够</strong>：要跑浮点滤波/电机 FOC → 必须有 M4 的 FPU；只是采数据发串口 → M0 都够。</li><li><strong>存储够不够</strong>：Flash 放代码和常量，RAM 放全局变量、栈、堆和 RTOS 任务栈。<strong>按最坏情况估，并留 30% 以上余量</strong>。</li><li><strong>外设对不对得上</strong>：需要几路 UART？要 CAN 吗？ADC 要几通道、多少位？USB 是 Device 还是 Host？</li><li><strong>供货与成本</strong>：量产项目里，供货稳定性和价格往往比性能更重要——这也是 F103 至今仍在大量出货的原因。</li></ol><div class="tip custom-block"><p class="custom-block-title">例 2 · 估算一个项目的资源够不够</p><p>某项目需求：采集 4 路传感器（ADC）、驱动一块 OLED（I²C）、串口上报（UART）、跑 FreeRTOS 管理 3 个任务。选 <code>STM32F103C8T6</code>（64 KB Flash / 20 KB SRAM）够吗？</p><p><strong>估 RAM</strong>（最容易先爆的）：</p><table tabindex="0"><thead><tr><th>用途</th><th>估算</th></tr></thead><tbody><tr><td>3 个 RTOS 任务栈，每个 512 字节</td><td>1.5 KB</td></tr><tr><td>FreeRTOS 内核与堆</td><td>约 4 KB</td></tr><tr><td>串口收发缓冲 + OLED 显存（128×64/8 = 1 KB）</td><td>约 2 KB</td></tr><tr><td>全局变量、ADC 缓冲</td><td>约 1 KB</td></tr><tr><td><strong>小计</strong></td><td><strong>约 8.5 KB</strong></td></tr></tbody></table><p>20 KB 装 8.5 KB，余量约 57%，<strong>够</strong>。但如果把任务栈加到 1 KB、再开一路 DMA 双缓冲，就会逼近 15 KB，此时应换 <code>CBT6</code>（128 KB Flash）或 <code>RCT6</code>（64 脚 / 256 KB Flash）同级更大容量的型号。</p><p><strong>估 Flash</strong>：带 HAL 库 + FreeRTOS 的工程中等规模约 40~60 KB，64 KB 会比较紧张，<strong>建议上 128 KB</strong>。结论：这个需求选 <code>STM32F103CBT6</code>（128 KB）更稳妥。</p></div><h2 id="六、最小系统-让一颗裸片跑起来需要什么" tabindex="-1">六、最小系统：让一颗裸片跑起来需要什么 <a class="header-anchor" href="#六、最小系统-让一颗裸片跑起来需要什么" aria-label="Permalink to &quot;六、最小系统：让一颗裸片跑起来需要什么&quot;">​</a></h2><p>一颗 STM32 芯片焊到板上，还必须有这四部分才能工作：</p><ol><li><strong>电源</strong>：VDD/VSS 多组引脚都要接，每组旁边放 100 nF 去耦电容（靠近引脚），再并一个 10 µF 的储能电容。</li><li><strong>复位</strong>：NRST 引脚，通常 10 kΩ 上拉 + 100 nF 到地构成上电复位（很多芯片内部已有上拉，外部可简化）。</li><li><strong>时钟</strong>：8 MHz 晶振（HSE）+ 两个负载电容（通常 20 pF 量级，具体看晶振要求）；RTC 另配 32.768 kHz。不用外部晶振也能跑（用内部 HSI），但精度差、波特率容易出问题。</li><li><strong>调试下载口</strong>：<strong>SWD 只需两根线</strong>（SWDIO、SWCLK）+ GND，比 JTAG 省引脚，是 ST-Link 的标准接法。再引出 VCC 即可给目标板供电（或由目标板自供电）。</li></ol><p>另外还有 <strong>BOOT0/BOOT1</strong> 引脚决定上电从哪里启动：BOOT0 = 0 从主 Flash 启动（正常工作），BOOT0 = 1 进入系统 BootLoader（可用串口下载程序，即 ISP）。</p><div class="tip custom-block"><p class="custom-block-title">例 3 · 拿到一块新板子，先确认什么</p><p>一块陌生的 STM32 板子，按这个顺序确认，能避开 80% 的「下载不进去」：</p><ol><li><strong>BOOT0 是否为低电平</strong>（从 Flash 启动）——如果 BOOT0 被意外拉高，程序下载成功也不会运行。</li><li><strong>SWD 四根线是否连通</strong>：SWDIO、SWCLK、GND，以及 VCC（用于电平参考，不一定要供电）。</li><li><strong>供电电压是 3.3 V 还是 5 V</strong>：STM32 的 IO 多数是 <strong>3.3 V 电平、5 V 容忍</strong>（标 FT 的引脚才容忍 5 V），接错会烧。</li><li><strong>外部晶振是否焊接</strong>——很多最小系统板的 8 MHz 晶振是贴片焊死的，但便宜板子可能用的是精度较差的晶振，导致串口通信误码。</li></ol></div><h2 id="七、工程实例" tabindex="-1">七、工程实例 <a class="header-anchor" href="#七、工程实例" aria-label="Permalink to &quot;七、工程实例&quot;">​</a></h2><p><strong>为什么 2026 年了还有大量产品在用 2007 年发布的 F103？</strong> 因为它已经不是「一款芯片」，而是一个<strong>生态</strong>：十几年的中文教程、成熟的原理图、大量已验证的代码、极低的单价和极稳的供货。工程选型里，「能被稳定复现」往往比「参数漂亮」更有价值。反过来，全新项目如果不需要兼容老代码，G0/G4 系列在价格和功耗上都更划算。</p><p><strong>为什么很多产品一颗芯片里既有 M4 又有 M0？</strong>（如 STM32WB、STM32MP1）因为两类任务的需求是冲突的：无线协议栈要求实时响应，应用逻辑要求算力。用一个小核专门跑协议栈、一个大核跑应用，比在一个核上硬挤要可靠得多——这和后面讲 RTOS 的「任务分离」是同一个思路。</p><h2 id="八、易错清单-自检" tabindex="-1">八、易错清单 + 自检 <a class="header-anchor" href="#八、易错清单-自检" aria-label="Permalink to &quot;八、易错清单 + 自检&quot;">​</a></h2><ul><li>[ ] <strong>MCU 和 MPU 的区别是「内存是否在片内」</strong>，不是主频高低</li><li>[ ] <strong>Cortex-M 是内核，不是芯片</strong>：同样是 M4，ST 和 NXP 的外设完全不同，外设代码不能直接搬</li><li>[ ] <strong>STM32 的 IO 是 3.3 V 电平</strong>，只有标注 FT 的引脚才容忍 5 V；接 5 V 器件要做电平转换</li><li>[ ] <strong>型号里的 Flash 容量码不是乘数</strong>：<code>8</code> = 64 KB、<code>B</code> = 128 KB、<code>C</code> = 256 KB、<code>E</code> = 512 KB，需要查表，不能猜</li><li>[ ] <strong>BOOT0 拉高会进 BootLoader</strong>，此时下载成功也不会运行用户程序（非常常见的「程序没跑」原因）</li><li>[ ] <strong>选型时先看 RAM 再看 Flash</strong>：带 RTOS 和协议栈的项目，RAM 往往先不够</li></ul><p><strong>自检</strong>：不看上表，说出 <code>STM32F103C8T6</code> 的内核、主频、引脚数、Flash 容量；并说明一个 MCU 最小系统必须包含哪四部分。（答案：Cortex-M3 / 72 MHz / 48 脚 / 64 KB；电源、复位、时钟、调试下载口）</p>`,38))])}const b=d(g,[["render",h]]);export{C as __pageData,b as default};
